import subprocess, os, pty
def run_with_pty(args):
    master, slave = pty.openpty()
    try:
        p = subprocess.Popen([os.path.abspath("./executable")]+args, stdin=slave, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, cwd="/tmp")
        os.close(slave)
        try:
            out, err = p.communicate(timeout=3)
            return p.returncode, out[:2000], err[:2000]
        except subprocess.TimeoutExpired:
            p.kill()
            out, err = p.communicate()
            return (p.returncode, out[:2000] if out else "", err[:2000] if err else "")
    finally:
        try: os.close(master)
        except: pass

for args in [["--filter=test"], ["--filter=", "--walker=file"], ["--filter=foo", "--walker-root=/tmp"]]:
    rc,out,err=run_with_pty(args)
    print(f"{args}: rc={rc} out={out[:1000]!r} err={err[:1000]!r}")
PY"}

