def validate_color_full(v):
    if v == "" or v.strip() == "":
        return v
    # Split by comma/whitespace, ignore empties
    tokens = [t for t in re.split(r"[,\s]+", v.strip()) if t != ""]
    valid_bases = ('dark','light','base16','16','bw')
    valid_names = ('fg','list-fg','selected-fg','preview-fg','bg','list-bg','selected-bg','preview-bg','input-bg','header-bg','footer-bg','hl','selected-hl','current-fg','fg+','current-bg','bg+','gutter','current-hl','hl+','alt-bg','alt-gutter','query','input-fg','ghost','disabled','info','border','list-border','scrollbar','separator','gap-line','preview-border','preview-scrollbar','input-border','header-border','footer-border','label','list-label','preview-label','input-label','header-label','footer-label','prompt','pointer','marker','spinner','header','header-fg','footer','footer-fg','nth','nomatch')
    valid_attrs = ('regular','strip','bold','underline','underline-double','underline-curly','underline-dotted','underline-dashed','reverse','dim','italic','strikethrough')
    valid_color_names = ('black','red','green','yellow','blue','magenta','cyan','white','bright-black','bright-red','bright-green','bright-yellow','bright-blue','bright-magenta','bright-cyan','bright-white','gray','grey')
    for tok in tokens:
        ltok = tok.lower()
        if ltok in valid_bases:
            continue
        if ":" not in tok:
            raise ValueError(f"invalid color specification: {tok.lower()}")
        # Split name and rest
        name_part, rest = tok.split(":", 1)
        lname = name_part.lower()
        if lname not in valid_names:
            raise ValueError(f"invalid color specification: {tok.lower()}")
        # Rest can be empty? "fg:" (empty rest) succeeds. Good. So if rest == "", ok.
        if rest == "":
            continue
        # Split rest by ":" into parts (each can be empty? "fg::bold" (empty middle) succeeds. Good. So allow empties, ignore? Actually "fg::bold" parts ["","bold"]? First empty ignored? Good. "fg:red:" (trailing empty) succeeds. Good. So ignore empties.
        parts = rest.split(":")
        for p in parts:
            if p == "":
                continue
            lp = p.lower()
            # Check if valid color or attr?
            # For nth, only attrs allowed (not colors). For others, either.
            is_attr = lp in valid_attrs
            is_color = False
            # Check color: -1, 0-255, #rrggbb, names
            if p == "-1" or lp == "-1":
                is_color = True
            elif re.fullmatch(r"[+-]?[0-9]+", p):
                try:
                    iv = int(p)
                    if 0 <= iv <= 255:
                        is_color = True
                    else:
                        is_color = False
                except:
                    is_color = False
            elif p.startswith("#"):
                # Must be # + 6 hex?
                if re.fullmatch(r"#[0-9a-fA-F]{6}", p):
                    is_color = True
                else:
                    is_color = False
            elif lp in valid_color_names:
                is_color = True
            else:
                is_color = False
            if lname == "nth":
                # Only attrs allowed
                if is_attr:
                    continue
                elif is_color:
                    raise ValueError("only ANSI attributes are allowed for 'nth' (regular, bold, underline, reverse, dim, italic, strikethrough)")
                else:
                    raise ValueError(f"invalid color specification: {tok.lower()}")
            else:
                if is_attr or is_color:
                    continue
                else:
                    raise ValueError(f"invalid color specification: {tok.lower()}")
    return v

